import heapq
import itertools

def match(orders):
    trades = []
    orders_dict = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':..., 'active':bool}
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = itertools.count()

    def match_incoming(side, price, qty, is_market, incoming_id):
        nonlocal trades
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while qty > 0 and heap:
            top = heap[0]
            oid = top[2]
            rec = orders_dict.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(heap)
                continue

            price_ok = True
            if not is_market:
                if side == 'buy':
                    price_ok = rec['price'] <= price
                else:
                    price_ok = rec['price'] >= price

            if not price_ok:
                break

            trade_qty = min(qty, rec['qty'])
            if side == 'buy':
                trades.append([incoming_id, oid, rec['price'], trade_qty])
            else:
                trades.append([oid, incoming_id, rec['price'], trade_qty])

            qty -= trade_qty
            rec['qty'] -= trade_qty

            if rec['qty'] == 0:
                rec['active'] = False
                heapq.heappop(heap)
            # else: incoming qty must be 0 now (since trade_qty = min), loop will end

        return qty

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            rec = orders_dict.get(oid)
            if rec is not None and rec['active']:
                rec['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, False, oid)
            if remaining > 0:
                s = next(seq_counter)
                rec = {'side': side, 'price': price, 'qty': remaining, 'seq': s, 'active': True}
                orders_dict[oid] = rec
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, s, oid))
                else:
                    heapq.heappush(sell_heap, (price, s, oid))
            else:
                # fully filled, still register as inactive filled record (optional)
                orders_dict[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': next(seq_counter), 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, False, oid)
            # discard remainder, no resting
            orders_dict[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': next(seq_counter), 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, True, oid)
            orders_dict[oid] = {'side': side, 'price': None, 'qty': remaining, 'seq': next(seq_counter), 'active': False}

    return trades

